import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { User, Mail, Lock, Eye, EyeOff, ChevronDown } from 'lucide-react';
import { BtnOrange, TextInput, C } from '../components/UI';
import { useApp } from '../context/AppContext';

const DIETARY_OPTIONS = ['Vegetarian', 'Non-Vegetarian', 'Vegan', 'Eggetarian', 'Keto', 'Diabetic Friendly'];

export default function SignUpScreen() {
  const navigate = useNavigate();
  const { setUser } = useApp();
  const [form, setForm] = useState({ name: '', email: '', password: '', confirm: '', dietary: '' });
  const [showPass, setShowPass] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const [error, setError] = useState('');

  function handle(key) { return e => setForm(f => ({ ...f, [key]: e.target.value })); }

  function handleCreate() {
    if (!form.name || !form.email || !form.password) { setError('Please fill all required fields.'); return; }
    if (form.password !== form.confirm) { setError('Passwords do not match.'); return; }
    setUser({ name: form.name, email: form.email, avatar: null });
    navigate('/preferences');
  }

  return (
    <div style={{
      minHeight: '100vh', maxWidth: 430, margin: '0 auto',
      background: '#111', padding: '0 24px',
      display: 'flex', flexDirection: 'column',
    }}>
      <button onClick={() => navigate(-1)} style={{ background: 'none', border: 'none', color: '#fff', cursor: 'pointer', padding: '20px 0 0', fontSize: 20, alignSelf: 'flex-start' }}>←</button>

      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', paddingBottom: 40 }}>
        <h1 style={{ fontSize: 30, fontWeight: 800, color: '#fff', marginBottom: 6 }}>Create Account</h1>
        <p style={{ color: '#777', fontSize: 14, marginBottom: 32 }}>Start your healthy journey</p>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <TextInput icon={User}  placeholder="Full Name"       value={form.name}    onChange={handle('name')} />
          <TextInput icon={Mail}  placeholder="Email"           value={form.email}   onChange={handle('email')} type="email" />
          <TextInput icon={Lock}  placeholder="Password"        value={form.password} onChange={handle('password')} type={showPass ? 'text' : 'password'}
            rightIcon={<button onClick={() => setShowPass(v => !v)} style={{ background: 'none', border: 'none', color: '#666', cursor: 'pointer' }}>{showPass ? <EyeOff size={16} /> : <Eye size={16} />}</button>}
          />
          <TextInput icon={Lock}  placeholder="Confirm Password" value={form.confirm} onChange={handle('confirm')} type="password" />

          {/* Dietary Preference Dropdown */}
          <div style={{ position: 'relative' }}>
            <div
              onClick={() => setShowDropdown(v => !v)}
              style={{
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                background: '#1e1e1e', border: '1px solid #2e2e2e',
                borderRadius: 10, padding: '13px 14px', cursor: 'pointer',
              }}
            >
              <span style={{ fontSize: 14, color: form.dietary ? '#fff' : '#555' }}>
                {form.dietary || 'Dietary Preference'}
              </span>
              <ChevronDown size={16} color="#666" />
            </div>
            {showDropdown && (
              <div style={{
                position: 'absolute', top: '110%', left: 0, right: 0, zIndex: 99,
                background: '#252525', borderRadius: 10, border: '1px solid #333',
                overflow: 'hidden',
              }}>
                {DIETARY_OPTIONS.map(opt => (
                  <div
                    key={opt}
                    onClick={() => { setForm(f => ({ ...f, dietary: opt })); setShowDropdown(false); }}
                    style={{
                      padding: '12px 16px', fontSize: 14, cursor: 'pointer',
                      color: form.dietary === opt ? C.orange : '#ccc',
                      background: form.dietary === opt ? 'rgba(255,107,53,0.08)' : 'transparent',
                      borderBottom: '1px solid #2a2a2a',
                    }}
                  >
                    {opt}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {error && <p style={{ color: '#ff4d6d', fontSize: 12, marginTop: 8 }}>{error}</p>}

        <div style={{ marginTop: 28 }}>
          <BtnOrange onClick={handleCreate}>Create Account</BtnOrange>
        </div>

        <p style={{ textAlign: 'center', color: '#666', fontSize: 13, marginTop: 20 }}>
          Already have an account?{' '}
          <span onClick={() => navigate('/signin')} style={{ color: C.orange, fontWeight: 700, cursor: 'pointer' }}>
            Sign In
          </span>
        </p>
      </div>
    </div>
  );
}
